<?php
function brand_sku_runs_ready(){global $CFG;$q=db()->prepare("SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=? AND TABLE_NAME='sku_conversion_runs'");$q->execute([$CFG['db_name']]);return (bool)$q->fetchColumn();}
function migrate_brand_sku_controls(){db()->exec("CREATE TABLE IF NOT EXISTS sku_conversion_runs(run_ref VARCHAR(100) PRIMARY KEY,run_json LONGTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");}
function brand_sku_enabled(){return setting('brand_sku_format','')==='brand-category-sequence';}
function brand_sku_prefixes(){
 $map=json_decode(setting('sku_brand_prefixes','{}'),true)?:[];$defaults=['RS8'=>'RS8','SRF'=>'SRF','Oils & Liquid Essentials'=>'OLE','Lumina Pro'=>'LPRO','Merchandise'=>'MERCH','Others'=>'OTH'];
 foreach(inventory_brand_options() as $brand){$key=norm($brand);if(isset($map[$key]))continue;$base=$defaults[$brand]??substr(preg_replace('/[^A-Z0-9]/','',strtoupper($brand)),0,10);if($base==='')$base='BR'.strtoupper(substr(hash('sha256',$brand),0,6));$prefix=$base;$n=1;while(in_array($prefix,$map,true))$prefix=substr($base,0,8).(++$n);$map[$key]=$prefix;}
 return $map;
}
function brand_sku_prefix($brand){$canonical=inventory_filter_brand($brand);return brand_sku_prefixes()[norm($canonical)];}
function brand_sku_owner($code){$ids=[];$q=db()->prepare('SELECT id FROM products WHERE master_sku=?');$q->execute([$code]);if($id=(int)$q->fetchColumn())$ids[$id]=true;$q=db()->prepare('SELECT product_id FROM product_code_aliases WHERE alias_code=?');$q->execute([norm($code)]);if($id=(int)$q->fetchColumn())$ids[$id]=true;$q=db()->prepare('SELECT DISTINCT product_id FROM platform_aliases WHERE normalized_alias=? OR external_id=?');$q->execute([norm($code),$code]);foreach($q as $r)$ids[(int)$r['product_id']]=true;$q=db()->prepare('SELECT product_id FROM receipt_aliases WHERE normalized_alias=?');$q->execute([norm($code)]);if($id=(int)$q->fetchColumn())$ids[$id]=true;if(count($ids)>1)throw new Exception('Conflicting current, old or mapped item code: '.$code);return (int)(array_key_first($ids)??0);}
function brand_sku_alias($code,$id,$ref){if(trim((string)$code)==='')return;$owner=brand_sku_owner($code);if($owner&&$owner!==(int)$id)throw new Exception('Item code belongs to another product: '.$code);db()->prepare('INSERT IGNORE INTO product_code_aliases(alias_code,product_id,original_code,migration_ref) VALUES(?,?,?,?)')->execute([norm($code),(int)$id,$code,$ref]);}
function product_next_sku($brand,$main,$sub,$reserve=false){
 if(!brand_sku_enabled())return category_next_sku($main,$sub,$reserve);
 if(!in_array($brand,inventory_brand_options(),true))throw new Exception('Select a registered brand.');
 [$main,$sub]=product_category_selection($main,$sub);$key=category_key($main,$sub===$main?'':$sub);$row=category_sequence($main,$sub===$main?'':$sub);$q=db()->prepare('SELECT * FROM category_sequences WHERE category_key=?'.($reserve?' FOR UPDATE':''));$q->execute([$key]);$row=$q->fetch();$n=max(1,(int)$row['next_number']);$prefix=brand_sku_prefix($brand).'-'.$row['prefix'];
 do{$code=$prefix.'-'.str_pad((string)$n,4,'0',STR_PAD_LEFT);if(!brand_sku_owner($code))break;$n++;}while(true);
 if($reserve){if(!db()->inTransaction())throw new Exception('Product creation must be transactional.');db()->prepare('UPDATE category_sequences SET next_number=? WHERE category_key=?')->execute([$n+1,$key]);set_setting('sku_brand_prefixes',json_encode(brand_sku_prefixes()));}return $code;
}
function brand_sku_retag($product,$brand,$main,$sub){
 if(!brand_sku_enabled()||inventory_filter_brand($product['brand'])===inventory_filter_brand($brand))return $product['master_sku'];
 if(!preg_match('/^[A-Z0-9]+-([A-Z0-9]+)-(\d{4,})$/D',(string)$product['master_sku'],$m))$new=product_next_sku($brand,$main,$sub,true);else{$new=brand_sku_prefix($brand).'-'.$m[1].'-'.$m[2];$owner=brand_sku_owner($new);if($owner&&$owner!==(int)$product['id'])$new=product_next_sku($brand,$main,$sub,true);}
 brand_sku_alias($product['master_sku'],$product['id'],'BRAND-CORRECTION');db()->prepare('UPDATE products SET master_sku=? WHERE id=?')->execute([$new,$product['id']]);set_setting('sku_brand_prefixes',json_encode(brand_sku_prefixes()));audit('Update product SKU brand','Product',(string)$product['id'],$product['master_sku'].' -> '.$new.'; brand correction; old code preserved as alias.');return $new;
}
function brand_sku_plan($reset=false){
 if(!item_codes_ready())throw new Exception('Run upgrade_item_codes.php first.');$products=db()->query('SELECT * FROM products ORDER BY id')->fetchAll();$aliases=db()->query('SELECT * FROM product_code_aliases ORDER BY alias_code')->fetchAll();$sequences=db()->query('SELECT * FROM category_sequences ORDER BY category_key')->fetchAll();$seqs=array_column($sequences,null,'category_key');$reserved=[];
 foreach($products as $p)if($p['master_sku'])$reserved[norm($p['master_sku'])]=(int)$p['id'];foreach($aliases as $a){$k=norm($a['alias_code']);if(isset($reserved[$k])&&$reserved[$k]!=(int)$a['product_id'])throw new Exception('Conflicting old code: '.$a['original_code']);$reserved[$k]=(int)$a['product_id'];}
 $mappings=db()->query('SELECT product_id,normalized_alias,external_id FROM platform_aliases ORDER BY id')->fetchAll();$receipts=db()->query('SELECT product_id,normalized_alias FROM receipt_aliases ORDER BY id')->fetchAll();foreach(array_merge($mappings,$receipts) as $a)foreach(['normalized_alias','external_id'] as $field){$v=norm($a[$field]??'');if(!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)?-\d{4,}$/D',$v))continue;if(isset($reserved[$v])&&$reserved[$v]!=(int)$a['product_id'])throw new Exception('Conflicting mapped item code: '.$v);$reserved[$v]=(int)$a['product_id'];}
 $grouped=[];foreach($products as $p){[$main,$sub]=product_category_selection($p['main_category'],$p['category']);$key=category_key($main,$sub===$main?'':$sub);if(!isset($seqs[$key]))throw new Exception('Missing category sequence: '.$main.' / '.$sub);$grouped[$key][]=$p;}$lines=[];$groups=[];
 foreach($grouped as $key=>$ps){$prefix=$seqs[$key]['prefix'];$used=[];$assigned=[];
  foreach($ps as $p){$old=(string)$p['master_sku'];if(preg_match('/^(?:[A-Z0-9]+-)?'.preg_quote($prefix,'/').'-(\d{4,})$/D',$old,$m)&&(int)$m[1]>0){$n=(int)$m[1];if(!isset($used[$n])){$used[$n]=true;$assigned[$p['id']]=$n;}}}
  foreach($ps as $p){$n=$assigned[$p['id']]??1;$bp=brand_sku_prefix($p['brand']);while(true){$candidate=$bp.'-'.$prefix.'-'.str_pad((string)$n,4,'0',STR_PAD_LEFT);$isUsed=isset($used[$n])&&($assigned[$p['id']]??0)!==$n;$owner=$reserved[norm($candidate)]??0;if(!$isUsed&&(!$owner||$owner===(int)$p['id']))break;$n++;}$used[$n]=true;$reserved[norm($candidate)]=(int)$p['id'];$lines[]=['id'=>(int)$p['id'],'old'=>$p['master_sku'],'new'=>$candidate,'name'=>$p['name'],'brand'=>$p['brand'],'main'=>$p['main_category'],'sub'=>$p['category'],'active'=>(int)$p['active']];}
  $groups[$key]=['prefix'=>$prefix,'main'=>$ps[0]['main_category'],'sub'=>$ps[0]['category'],'products'=>count($ps),'next_number'=>max((int)$seqs[$key]['next_number'],max(array_keys($used))+1)];
 }
 $prefixes=brand_sku_prefixes();return ['lines'=>$lines,'groups'=>$groups,'prefixes'=>$prefixes,'changed'=>count(array_filter($lines,fn($l)=>$l['old']!==$l['new'])),'snapshot'=>$reset?item_code_snapshot():hash('sha256',json_encode([$products,$aliases,$sequences,$prefixes,$mappings,$receipts]))];
}
function brand_sku_require_admin(){if(current_user()['role']!=='Admin')throw new Exception('Administrator access required.');if(!item_codes_ready())throw new Exception('Run upgrade_item_codes.php first.');}
function brand_sku_run($ref){if(!preg_match('/^BSKU-[A-Za-z0-9-]+$/D',(string)$ref))throw new Exception('Invalid conversion reference.');$q=db()->prepare('SELECT run_json FROM sku_conversion_runs WHERE run_ref=?');$q->execute([$ref]);$raw=$q->fetchColumn();if(!$raw)throw new Exception('Conversion preview not found.');return json_decode($raw,true,512,JSON_THROW_ON_ERROR);}
function brand_sku_prepare(){brand_sku_require_admin();migrate_brand_sku_controls();brand_sku_plan();$id=backup_create();backup_verify_restore($id);$plan=brand_sku_plan();$ref=next_ref('BSKU').'-'.bin2hex(random_bytes(4));$run=['ref'=>$ref,'status'=>'Prepared','backup_id'=>$id,'plan'=>$plan,'digest'=>hash('sha256',json_encode($plan)),'prepared_at'=>date('Y-m-d H:i:s'),'created_by'=>current_user()['id']];db()->prepare('INSERT INTO sku_conversion_runs(run_ref,run_json) VALUES(?,?)')->execute([$ref,json_encode($run)]);return $ref;}
function brand_sku_preserved(){
 $hashes=[];foreach(item_code_scope()['clear'] as $t)if($t!=='activity_log')$hashes[$t]=backup_rows_hash(db()->query('SELECT * FROM `'.$t.'`')->fetchAll());foreach(['platform_aliases','receipt_aliases','users','allocation_rules','product_audit','brands','categories','managed_categories'] as $t)$hashes[$t]=backup_rows_hash(db()->query('SELECT * FROM `'.$t.'`')->fetchAll());return $hashes;
}
function brand_sku_apply($ref,$digest,$confirmation,$ack){
 brand_sku_require_admin();if(!$ack||$confirmation!=='APPLY BRAND SKU FORMAT')throw new Exception('Review the mapping and type APPLY BRAND SKU FORMAT.');return process_transaction(function()use($ref,$digest){
  $q=db()->prepare('SELECT run_json FROM sku_conversion_runs WHERE run_ref=? FOR UPDATE');$q->execute([$ref]);$run=brand_sku_run($ref);if($run['status']!=='Prepared')throw new Exception('This conversion is already applied.');if(!hash_equals($run['digest'],(string)$digest))throw new Exception('Preview token changed.');if(brand_sku_plan()!==$run['plan'])throw new Exception('Product codes, brands or categories changed. Prepare a fresh verified preview.');
  $b=backup_record($run['backup_id']);if($b['restore_test_status']!=='Passed')throw new Exception('Verified backup required.');$zip=new ZipArchive();if($zip->open($b['path'])!==true)throw new Exception('Backup unavailable.');try{$m=json_decode($zip->getFromName('backup_manifest.json'),true,512,JSON_THROW_ON_ERROR);foreach($m['files'] as $f=>$h)if(!hash_equals($h,hash('sha256',$zip->getFromName($f))))throw new Exception('Backup integrity failed.');}finally{$zip->close();}
  $preserved=brand_sku_preserved();$before=db()->query('SELECT * FROM products ORDER BY id FOR UPDATE')->fetchAll();
  foreach($run['plan']['lines'] as $l){brand_sku_alias($l['old'],$l['id'],$ref);if($l['old']!==$l['new'])db()->prepare('UPDATE products SET master_sku=? WHERE id=?')->execute(['TMP-BSKU-'.substr(hash('sha256',$ref),0,10).'-'.$l['id'],$l['id']]);}
  foreach($run['plan']['lines'] as $l)if($l['old']!==$l['new'])db()->prepare('UPDATE products SET master_sku=? WHERE id=?')->execute([$l['new'],$l['id']]);foreach($run['plan']['groups'] as $k=>$g)db()->prepare('UPDATE category_sequences SET next_number=GREATEST(next_number,?) WHERE category_key=?')->execute([$g['next_number'],$k]);
  set_setting('sku_brand_prefixes',json_encode($run['plan']['prefixes']));set_setting('brand_sku_format','brand-category-sequence');
  $clean=function($ps){foreach($ps as &$p)unset($p['master_sku'],$p['updated_at']);return $ps;};if($clean($before)!==$clean(db()->query('SELECT * FROM products ORDER BY id')->fetchAll()))throw new Exception('Unexpected product changes.');if($preserved!==brand_sku_preserved())throw new Exception('Unexpected stock, history or mapping changes. Conversion rolled back.');
  foreach($run['plan']['lines'] as $l){$q=db()->prepare('SELECT master_sku FROM products WHERE id=?');$q->execute([$l['id']]);if($q->fetchColumn()!==$l['new'])throw new Exception('Code verification failed.');if($l['active']&&$l['old']&&product_code_lookup($l['old'])!==$l['id'])throw new Exception('Old-code lookup failed.');}
  $run['status']='Applied';$run['applied_at']=date('Y-m-d H:i:s');$run['applied_by']=current_user()['id'];db()->prepare('UPDATE sku_conversion_runs SET run_json=? WHERE run_ref=?')->execute([json_encode($run),$ref]);audit('Brand SKU conversion','System',$ref,$run['plan']['changed'].' codes updated; stocks, transactions, mappings, users and history preserved; backup #'.$run['backup_id']);return $run['plan']['changed'];
 });
}
